#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int ROOT = 15311432;
const int INVROOT = 469870224;

int reverseBits(int n, int k) {
    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long modularInverse(int a) {
    long long result = 1, base = a, exp = MOD - 2;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long modularExponentiation(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

void ntt(std::vector<long long>& arr, int logN, bool invert) {
    int baseRoot = invert ? INVROOT : ROOT;
    long long root = modularExponentiation(baseRoot, (1 << (23 - logN)));
    std::vector<long long> roots(logN);
    roots[logN - 1] = root;
    for (int i = logN - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    for (int s = 0; s < logN; s++) {
        int len = 1 << s;
        for (int start = 0; start < (int)arr.size(); start += 2 * len) {
            long long curRoot = 1;
            for (int j = start; j < start + len; j++) {
                long long t = (curRoot * arr[j + len]) % MOD;
                long long u = arr[j];
                arr[j] = (u + t) % MOD;
                arr[j + len] = (u - t + MOD) % MOD;
                curRoot = (roots[s] * curRoot) % MOD;
            }
        }
    }
    if (invert) {
        long long invSize = modularInverse((int)arr.size());
        for (auto& x : arr) {
            x = (x * invSize) % MOD;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
    }
    std::sort(nums.begin(), nums.end());
    int minSize = n * nums[m - 1] + 2;
    int logSize = 0, size = 1;
    while (size < minSize) {
        size <<= 1;
        logSize++;
    }
    vector<long long> array(size, 0);
    for (int num : nums) {
        array[reverseBits(num, logSize)] = 1;
    }
    ntt(array, logSize, false);
    for (int i = 0; i < size; i++) {
        long long val = array[i] % MOD;
        long long powVal = 1;
        for (int j = 0; j < n; j++) {
            powVal = (powVal * val) % MOD;
        }
        array[i] = powVal;
    }
    vector<long long> tempArray(size, 0);
    for (int i = 0; i < size; i++) {
        tempArray[reverseBits(i, logSize)] = array[i] % MOD;
    }
    array = tempArray;
    ntt(array, logSize, true);
    long long totalSum = 0;
    for (int i = 0; i < size; i++) {
        totalSum = (totalSum + array[i] * array[i]) % MOD;
    }
    long long invSize = modularInverse(size);
    long long result = ((totalSum % MOD) * (invSize % MOD)) % MOD;
    result = (result * invSize) % MOD;
    cout << result << "\n";
    return 0;
}

